// Services Management Component
function ServicesManagement() {
  const { services, isLoading, createService, updateService, deleteService } = useServices();
  const { getAuthHeaders } = useAuth();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingService, setEditingService] = useState(null);
  const [formData, setFormData] = useState({
    title: "", description: "", icon: "Code", color: "blue",
    category: "", displayOrder: 0, gridSpan: 1,
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingService) {
        await updateService.mutateAsync({ id: editingService._id, data: formData });
        toast.success("Service updated successfully!");
      } else {
        await createService.mutateAsync(formData);
        toast.success("Service created successfully!");
      }
      setIsModalOpen(false);
      setEditingService(null);
      resetForm();
    } catch (error) {
      toast.error(error.response?.data?.error || "Failed to save service");
    }
  };

  const handleEdit = (service) => {
    setEditingService(service);
    setFormData({
      title: service.title, description: service.description,
      icon: service.icon === "HandshakeIcon" ? "Cog" : service.icon || "Code",
      color: service.color || "blue", category: service.category,
      displayOrder: service.displayOrder || 0, gridSpan: service.gridSpan || 1,
    });
    setIsModalOpen(true);
  };

  const handleDelete = async (id) => {
    if (confirm("Are you sure you want to delete this service?")) {
      try {
        await deleteService.mutateAsync(id);
        toast.success("Service deleted successfully!");
      } catch (error) {
        toast.error(error.response?.data?.error || "Failed to delete service");
      }
    }
  };

  const resetForm = () => {
    setFormData({ title: "", description: "", icon: "Code", color: "blue",
      category: "", displayOrder: 0, gridSpan: 1 });
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-2xl font-bold text-white">Services Management</h2>
        <Button onClick={() => { setEditingService(null); resetForm(); setIsModalOpen(true); }}
          className="bg-[#FFB633] text-black hover:bg-[#e5a32e]">
          <Plus className="w-4 h-4 mr-2" /> Add Service
        </Button>
      </div>

      {isLoading ? (
        <div className="text-gray-400">Loading services...</div>
      ) : services.length === 0 ? (
        <div className="text-center py-12 bg-[#1a1a1b] rounded-xl border border-white/10">
          <Briefcase className="w-12 h-12 text-gray-600 mx-auto mb-4" />
          <p className="text-gray-400">No services yet. Create your first service!</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {services.map((service) => {
            const IconComponent = iconMap[service.icon] || Code;
            return (
              <motion.div key={service._id} whileHover={{ scale: 1.02 }}
                className="bg-[#1a1a1b] rounded-xl p-6 border border-white/10">
                <div className="flex items-start justify-between mb-4">
                  <div className="p-3 rounded-lg"
                    style={{ backgroundColor: colorMap[service.color] || "#3B82F6" }}>
                    <IconComponent className="w-6 h-6 text-white" />
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => handleEdit(service)}
                      className="p-2 text-gray-400 hover:text-white hover:bg-white/10 rounded-lg transition-colors">
                      <Edit className="w-4 h-4" />
                    </button>
                    <button onClick={() => handleDelete(service._id)}
                      className="p-2 text-gray-400 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
                <h3 className="text-lg font-semibold text-white mb-2">{service.title}</h3>
                <p className="text-gray-400 text-sm mb-4 line-clamp-2">{service.description}</p>
                <div className="flex flex-wrap gap-2">
                  <span className="px-2 py-1 bg-white/10 rounded text-xs text-gray-300">{service.category}</span>
                  <span className="px-2 py-1 bg-white/10 rounded text-xs text-gray-300">Grid: {service.gridSpan || 1}</span>
                </div>
              </motion.div>
            );
          })}
        </div>
      )}

      {/* Add/Edit Modal */}
      <Dialog open={isModalOpen} onOpenChange={setIsModalOpen}>
        <DialogContent className="bg-[#1a1a1b] border-white/10 text-white max-w-lg">
          <DialogHeader>
            <DialogTitle>{editingService ? "Edit Service" : "Add New Service"}</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4 mt-4">
            <div>
              <Label className="text-white">Title</Label>
              <Input value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                placeholder="Service title" required
                className="bg-white/5 border-white/10 text-white mt-1" />
            </div>
            <div>
              <Label className="text-white">Description</Label>
              <textarea value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Service description" required rows={3}
                className="w-full bg-white/5 border border-white/10 text-white rounded-md px-3 py-2 mt-1" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label className="text-white">Icon</Label>
                <Select value={formData.icon}
                  onValueChange={(v) => setFormData({ ...formData, icon: v })}>
                  <SelectTrigger className="bg-white/5 border-white/10 text-white mt-1">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-[#2a2a2b] border-white/10">
                    {iconOptions.map((icon) => {
                      const IconOption = iconMap[icon] || Code;
                      const label = icon === "Bot" ? "Robot (AI Tasks)"
                        : icon === "BrainCircuit" ? "AI / Brain Circuit"
                        : icon === "Cog" ? "Engine" : icon;
                      return (
                        <SelectItem key={icon} value={icon} className="text-white hover:bg-white/10">
                          <span className="flex items-center gap-2">
                            <IconOption className="h-4 w-4" /> {label}
                          </span>
                        </SelectItem>
                      );
                    })}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label className="text-white">Color</Label>
                <Select value={formData.color}
                  onValueChange={(v) => setFormData({ ...formData, color: v })}>
                  <SelectTrigger className="bg-white/5 border-white/10 text-white mt-1">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-[#2a2a2b] border-white/10">
                    {colorOptions.map((color) => (
                      <SelectItem key={color} value={color} className="text-white hover:bg-white/10">
                        <div className="flex items-center gap-2">
                          <div className="w-4 h-4 rounded" style={{ backgroundColor: colorMap[color] }} />
                          {color}
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div>
              <Label className="text-white">Category</Label>
              <Input value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                placeholder="e.g., Web Development" required
                className="bg-white/5 border-white/10 text-white mt-1" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label className="text-white">Display Order</Label>
                <Input type="number" value={formData.displayOrder}
                  onChange={(e) => setFormData({ ...formData, displayOrder: parseInt(e.target.value) || 0 })}
                  className="bg-white/5 border-white/10 text-white mt-1" />
              </div>
              <div>
                <Label className="text-white">Grid Span (1-7)</Label>
                <Input type="number" min={1} max={7} value={formData.gridSpan}
                  onChange={(e) => setFormData({ ...formData,
                    gridSpan: Math.min(7, Math.max(1, parseInt(e.target.value) || 1)) })}
                  className="bg-white/5 border-white/10 text-white mt-1" />
              </div>
            </div>
            <Button type="submit" className="w-full bg-[#FFB633] text-black hover:bg-[#e5a32e]">
              {editingService ? "Update Service" : "Create Service"}
            </Button>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

