// Users Management Component
function UsersManagement() {
  const { getAuthHeaders } = useAuth();
  const [users, setUsers] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [passwordModalOpen, setPasswordModalOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [newPassword, setNewPassword] = useState("");

  useEffect(() => { fetchUsers(); }, []);

  const fetchUsers = async () => {
    try {
      const response = await axios.get("/api/users", { headers: getAuthHeaders() });
      setUsers(response.data);
    } catch (error) {
      console.error("Failed to fetch users:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleToggleAdmin = async (user) => {
    try {
      await axios.put(`/api/users/${user._id}`, { isAdmin: !user.isAdmin },
        { headers: getAuthHeaders() });
      toast.success(`User ${user.isAdmin ? "demoted from" : "promoted to"} admin!`);
      fetchUsers();
    } catch (error) {
      toast.error(error.response?.data?.error || "Failed to update user");
    }
  };

  const handleDelete = async (id) => {
    if (confirm("Are you sure you want to delete this user?")) {
      try {
        await axios.delete(`/api/users/${id}`, { headers: getAuthHeaders() });
        toast.success("User deleted successfully!");
        fetchUsers();
      } catch (error) {
        toast.error(error.response?.data?.error || "Failed to delete user");
      }
    }
  };

  const openPasswordModal = (user) => {
    setSelectedUser(user);
    setNewPassword("");
    setPasswordModalOpen(true);
  };

  const handleSetPassword = async (e) => {
    e.preventDefault();
    if (newPassword.length < 6) {
      toast.error("Password must be at least 6 characters");
      return;
    }
    try {
      await axios.put(`/api/users/${selectedUser._id}`, { password: newPassword },
        { headers: getAuthHeaders() });
      toast.success(`Password updated for ${selectedUser.name}`);
      setPasswordModalOpen(false);
      setSelectedUser(null);
      setNewPassword("");
    } catch (error) {
      toast.error(error.response?.data?.error || "Failed to set password");
    }
  };
